using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new StudentsController(_context);
        _controller.TempData = new TempDataDictionary(new DefaultHttpContext(), new SessionStateTempDataProvider()); // use a mock-free approach
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Student CreateStudent(string last = "Smith", string first = "John", DateTime? date = null)
    {
        var student = new Student
        {
            LastName = last,
            FirstMidName = first,
            EnrollmentDate = date ?? new DateTime(2023, 9, 1)
        };
        _context.Students.Add(student);
        _context.SaveChanges();
        return student;
    }

    [Fact]
    public void Index_ReturnsView_WithStudentsOrderedByLastName()
    {
        CreateStudent("Zeta", "Alice");
        CreateStudent("Alpha", "Bob");

        var result = _controller.Index(null, null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Alpha", model[0].LastName);
        Assert.Equal("Zeta", model[1].LastName);
    }

    [Theory]
    [InlineData("name_desc", "Zeta")]
    [InlineData("", "Alpha")]
    public void Index_SortOrder_AppliesCorrectOrdering(string sortOrder, string expectedFirstLastName)
    {
        CreateStudent("Zeta", "Alice");
        CreateStudent("Alpha", "Bob");

        var result = _controller.Index(sortOrder, null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(expectedFirstLastName, model[0].LastName);
    }

    [Fact]
    public void Index_SearchString_FiltersStudents()
    {
        CreateStudent("Smith", "John");
        CreateStudent("Johnson", "Jane");

        var result = _controller.Index(null, null, "Smith", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Smith", model[0].LastName);
    }

    [Fact]
    public void Index_DateSort_OrdersByEnrollmentDate()
    {
        CreateStudent("A", "A", new DateTime(2024, 1, 1));
        CreateStudent("B", "B", new DateTime(2022, 1, 1));

        var result = _controller.Index("Date", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal("B", model[0].LastName);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsStudentView()
    {
        var student = CreateStudent();

        var result = _controller.Details(student.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithDefaultDate()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    [Fact]
    public void Create_Post_ValidStudent_RedirectsToIndex()
    {
        var student = new Student
        {
            LastName = "Doe",
            FirstMidName = "Jane",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        var result = _controller.Create(student);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Single(_context.Students);
    }

    [Fact]
    public void Create_Post_InvalidEnrollmentDate_ReturnsView()
    {
        var student = new Student
        {
            LastName = "Doe",
            FirstMidName = "Jane",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Create_Post_DateOutOfRange_ReturnsView()
    {
        var student = new Student
        {
            LastName = "Doe",
            FirstMidName = "Jane",
            EnrollmentDate = new DateTime(1000, 1, 1)
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Edit(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithStudent()
    {
        var student = CreateStudent();

        var result = _controller.Edit(student.ID) as ViewResult;

        Assert.NotNull(result);
        Assert.Equal(student.ID, ((Student)result.Model!).ID);
    }

    [Fact]
    public void Edit_Post_ValidStudent_RedirectsToIndex()
    {
        var student = CreateStudent();
        student.LastName = "Updated";

        // Detach existing tracked entity to avoid tracking conflict
        _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var result = _controller.Edit(student);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_Post_InvalidDate_ReturnsView()
    {
        var student = CreateStudent();
        student.EnrollmentDate = DateTime.MinValue;

        _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var result = _controller.Edit(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Delete(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsView()
    {
        var student = CreateStudent();

        var result = _controller.Delete(student.ID) as ViewResult;

        Assert.NotNull(result);
        Assert.Equal(student.ID, ((Student)result.Model!).ID);
    }

    [Fact]
    public void DeleteConfirmed_RemovesStudent_RedirectsToIndex()
    {
        var student = CreateStudent();

        var result = _controller.DeleteConfirmed(student.ID);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Empty(_context.Students);
    }

    [Fact]
    public void Index_Pagination_RespectsPageSize()
    {
        for (int i = 0; i < 15; i++)
            CreateStudent($"Student{i:D2}", "Test");

        var result = _controller.Index(null, null, null, 1) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(10, model.Count);
        Assert.True(model.HasNextPage);
        Assert.False(model.HasPreviousPage);
    }

    [Fact]
    public void Index_Page2_ShowsRemainingStudents()
    {
        for (int i = 0; i < 15; i++)
            CreateStudent($"Student{i:D2}", "Test");

        var result = _controller.Index(null, null, null, 2) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
        Assert.Equal(5, model.Count);
        Assert.True(model.HasPreviousPage);
        Assert.False(model.HasNextPage);
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;

namespace ContosoUniversity.Tests.Controllers;

public class CoursesControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _envMock;
    private readonly Mock<ILogger<CoursesController>> _loggerMock;

    public CoursesControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _envMock = new Mock<IWebHostEnvironment>();
        _envMock.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
        _envMock.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
        _loggerMock = new Mock<ILogger<CoursesController>>();
        _controller = new CoursesController(_context, _envMock.Object, _loggerMock.Object);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Department CreateDepartment(string name = "Engineering")
    {
        var dept = new Department
        {
            Name = name,
            Budget = 100000,
            StartDate = new DateTime(2020, 1, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    private Course CreateCourse(int courseId = 1001, string title = "Calculus", int credits = 3, Department? dept = null)
    {
        dept ??= CreateDepartment();
        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = credits,
            DepartmentID = dept.DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    [Fact]
    public void Index_ReturnsViewWithCourses()
    {
        var dept = CreateDepartment();
        CreateCourse(1001, "Calculus", 3, dept);
        CreateCourse(1002, "Physics", 4, dept);

        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
        Assert.Equal(2, model.Count);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsCourse()
    {
        var course = CreateCourse();

        var result = _controller.Details(course.CourseID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal(course.CourseID, model.CourseID);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithDepartmentList()
    {
        CreateDepartment("Math");

        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(_controller.ViewBag.DepartmentID);
    }

    [Fact]
    public void Create_Post_ValidCourse_NoFile_RedirectsToIndex()
    {
        var dept = CreateDepartment();
        var course = new Course
        {
            CourseID = 2001,
            Title = "Algebra",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };

        var result = _controller.Create(course, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.NotNull(_context.Courses.Find(2001));
    }

    [Fact]
    public void Create_Post_InvalidExtension_ReturnsView()
    {
        var dept = CreateDepartment();
        var course = new Course
        {
            CourseID = 2002,
            Title = "Bio",
            Credits = 2,
            DepartmentID = dept.DepartmentID
        };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("test.exe");
        fileMock.Setup(f => f.Length).Returns(1024);

        var result = _controller.Create(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Create_Post_FileTooLarge_ReturnsView()
    {
        var dept = CreateDepartment();
        var course = new Course
        {
            CourseID = 2003,
            Title = "Chemistry",
            Credits = 4,
            DepartmentID = dept.DepartmentID
        };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("test.jpg");
        fileMock.Setup(f => f.Length).Returns(10 * 1024 * 1024); // 10MB

        var result = _controller.Create(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Create_Post_ValidFile_SavesAndRedirects()
    {
        var dept = CreateDepartment();
        var course = new Course
        {
            CourseID = 2004,
            Title = "Art",
            Credits = 2,
            DepartmentID = dept.DepartmentID
        };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("material.png");
        fileMock.Setup(f => f.Length).Returns(1024);
        fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

        var result = _controller.Create(course, fileMock.Object);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        var saved = _context.Courses.Find(2004);
        Assert.NotNull(saved);
        Assert.Contains("/Uploads/TeachingMaterials/", saved.TeachingMaterialImagePath);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
