using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;

namespace ContosoUniversity.Tests.Controllers;

public class CoursesControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _envMock;
    private readonly Mock<ILogger<CoursesController>> _loggerMock;

    public CoursesControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _envMock = new Mock<IWebHostEnvironment>();
        _envMock.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
        _envMock.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
        _loggerMock = new Mock<ILogger<CoursesController>>();
        _controller = new CoursesController(_context, _envMock.Object, _loggerMock.Object);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Department CreateDepartment(string name = "Engineering")
    {
        var dept = new Department
        {
            Name = name,
            Budget = 100000,
            StartDate = new DateTime(2020, 1, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    private Course CreateCourse(int courseId = 1001, string title = "Calculus", int credits = 3, Department? dept = null)
    {
        dept ??= CreateDepartment();
        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = credits,
            DepartmentID = dept.DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    [Fact]
    public void Index_ReturnsViewWithCourses()
    {
        var dept = CreateDepartment();
        CreateCourse(1001, "Calculus", 3, dept);
        CreateCourse(1002, "Physics", 4, dept);

        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
        Assert.Equal(2, model.Count);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsCourse()
    {
        var course = CreateCourse();

        var result = _controller.Details(course.CourseID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal(course.CourseID, model.CourseID);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithDepartmentList()
    {
        CreateDepartment("Math");

        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(_controller.ViewBag.DepartmentID);
    }

    [Fact]
    public void Create_Post_ValidCourse_NoFile_RedirectsToIndex()
    {
        var dept = CreateDepartment();
        var course = new Course
        {
            CourseID = 2001,
            Title = "Algebra",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };

        var result = _controller.Create(course, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.NotNull(_context.Courses.Find(2001));
    }

    [Fact]
    public void Create_Post_InvalidExtension_ReturnsView()
    {
        var dept = CreateDepartment();
        var course = new Course
        {
            CourseID = 2002,
            Title = "Bio",
            Credits = 2,
            DepartmentID = dept.DepartmentID
        };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("test.exe");
        fileMock.Setup(f => f.Length).Returns(1024);

        var result = _controller.Create(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Create_Post_FileTooLarge_ReturnsView()
    {
        var dept = CreateDepartment();
        var course = new Course
        {
            CourseID = 2003,
            Title = "Chemistry",
            Credits = 4,
            DepartmentID = dept.DepartmentID
        };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("test.jpg");
        fileMock.Setup(f => f.Length).Returns(10 * 1024 * 1024); // 10MB

        var result = _controller.Create(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Create_Post_ValidFile_SavesAndRedirects()
    {
        var dept = CreateDepartment();
        var course = new Course
        {
            CourseID = 2004,
            Title = "Art",
            Credits = 2,
            DepartmentID = dept.DepartmentID
        };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("material.png");
        fileMock.Setup(f => f.Length).Returns(1024);
        fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

        var result = _controller.Create(course, fileMock.Object);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        var saved = _context.Courses.Find(2004);
        Assert.NotNull(saved);
        Assert.Contains("/Uploads/TeachingMaterials/", saved.TeachingMaterialImagePath);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        var dept = CreateDepartment();
        var course = new Course { CourseID = 2005, DepartmentID = dept.DepartmentID };
        _controller.ModelState.AddModelError("Title", "Required");

        var result = _controller.Create(course, null!) as ViewResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null);

        Assert.IsType<StatusCodeResult>(result);
    }

    [Fact]
    public void Edit_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Edit(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsView()
    {
        var course = CreateCourse();

        var result = _controller.Edit(course.CourseID) as ViewResult;

        Assert.NotNull(result);
        Assert.Equal(course.CourseID, ((Course)result.Model!).CourseID);
    }

    [Fact]
    public void Edit_Post_ValidCourse_NoFile_RedirectsToIndex()
    {
        var course = CreateCourse(3001, "Edited");
        _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        course.Title = "Updated";

        var result = _controller.Edit(course, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_Post_InvalidExtension_ReturnsView()
    {
        var course = CreateCourse(3002, "ToEdit");
        _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns("bad.txt");
        fileMock.Setup(f => f.Length).Returns(100);

        var result = _controller.Edit(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
    }

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        Assert.IsType<StatusCodeResult>(result);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsView()
    {
        var course = CreateCourse(4001, "ToDelete");

        var result = _controller.Delete(course.CourseID) as ViewResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void DeleteConfirmed_RemovesCourse_Redirects()
    {
        var course = CreateCourse(4002, "Remove");

        var result = _controller.DeleteConfirmed(course.CourseID);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Null(_context.Courses.Find(4002));
    }
}

