using ContosoUniversity.Models;

namespace ContosoUniversity.Tests;

public class ModelTests
{
    [Fact]
    public void Person_FullName_ReturnsLastCommaFirst()
    {
        var student = new Student
        {
            LastName = "Smith",
            FirstMidName = "John",
            EnrollmentDate = DateTime.Now
        };

        Assert.Equal("Smith, John", student.FullName);
    }

    [Fact]
    public void Student_InheritsFromPerson()
    {
        var student = new Student();

        Assert.IsAssignableFrom<Person>(student);
    }

    [Fact]
    public void Instructor_InheritsFromPerson()
    {
        var instructor = new Instructor();

        Assert.IsAssignableFrom<Person>(instructor);
    }

    [Fact]
    public void Instructor_FullName_ReturnsCorrectFormat()
    {
        var instructor = new Instructor
        {
            LastName = "Fakhouri",
            FirstMidName = "Fadi"
        };

        Assert.Equal("Fakhouri, Fadi", instructor.FullName);
    }

    [Fact]
    public void Notification_DefaultIsRead_IsFalse()
    {
        var notification = new Notification();

        Assert.False(notification.IsRead);
    }

    [Fact]
    public void Notification_Properties_SetCorrectly()
    {
        var now = DateTime.Now;
        var notification = new Notification
        {
            Id = 1,
            EntityType = "Student",
            EntityId = "42",
            Operation = "CREATE",
            Message = "Test message",
            CreatedAt = now,
            CreatedBy = "Admin",
            IsRead = true,
            ReadAt = now
        };

        Assert.Equal(1, notification.Id);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("Test message", notification.Message);
        Assert.Equal(now, notification.CreatedAt);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.True(notification.IsRead);
        Assert.Equal(now, notification.ReadAt);
    }

    [Theory]
    [InlineData(Grade.A)]
    [InlineData(Grade.B)]
    [InlineData(Grade.C)]
    [InlineData(Grade.D)]
    [InlineData(Grade.F)]
    public void Enrollment_Grade_AcceptsAllValues(Grade grade)
    {
        var enrollment = new Enrollment { Grade = grade };

        Assert.Equal(grade, enrollment.Grade);
    }

    [Fact]
    public void Enrollment_Grade_CanBeNull()
    {
        var enrollment = new Enrollment { Grade = null };

        Assert.Null(enrollment.Grade);
    }

    [Fact]
    public void Course_Properties_SetCorrectly()
    {
        var course = new Course
        {
            CourseID = 1050,
            Title = "Chemistry",
            Credits = 3,
            DepartmentID = 1,
            TeachingMaterialImagePath = "/images/chem.png"
        };

