using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests.Data;

public class DbInitializerTests
{
    [Fact]
    public void Initialize_EmptyDatabase_SeedsAllData()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        Assert.Equal(8, context.Students.Count());
        Assert.Equal(5, context.Instructors.Count());
        Assert.Equal(4, context.Departments.Count());
        Assert.Equal(7, context.Courses.Count());
        Assert.Equal(3, context.OfficeAssignments.Count());
        Assert.Equal(8, context.CourseAssignments.Count());
        Assert.Equal(11, context.Enrollments.Count());
    }

    [Fact]
    public void Initialize_AlreadySeeded_DoesNotDuplicate()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);
        DbInitializer.Initialize(context); // call twice

        Assert.Equal(8, context.Students.Count());
    }

    [Fact]
    public void Initialize_SetsCorrectStudentData()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        var carson = context.Students.Single(s => s.LastName == "Alexander");
        Assert.Equal("Carson", carson.FirstMidName);
        Assert.Equal(new DateTime(2010, 9, 1), carson.EnrollmentDate);
    }

    [Fact]
    public void Initialize_SetsInstructorHireDates()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        var kim = context.Instructors.Single(i => i.LastName == "Abercrombie");
        Assert.Equal(new DateTime(1995, 3, 11), kim.HireDate);
    }

    [Fact]
    public void Initialize_AssignsDepartmentAdministrators()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        var english = context.Departments.Single(d => d.Name == "English");
        var admin = context.Instructors.Find(english.InstructorID);
        Assert.Equal("Abercrombie", admin!.LastName);
    }

    [Fact]
    public void Initialize_CreatesOfficeAssignments()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        var fakhouri = context.Instructors.Single(i => i.LastName == "Fakhouri");
        var office = context.OfficeAssignments.Find(fakhouri.ID);
        Assert.Equal("Smith 17", office!.Location);
    }

    [Fact]
    public void Initialize_CreatesCourseAssignments()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        var assignments = context.CourseAssignments.ToList();
        Assert.Contains(assignments, a => a.CourseID == 1050); // Chemistry
    }

    [Fact]
    public void Initialize_CreatesEnrollmentsWithGrades()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        var alexander = context.Students.Single(s => s.LastName == "Alexander");
        var enrollment = context.Enrollments
            .Single(e => e.StudentID == alexander.ID && e.CourseID == 1050);
        Assert.Equal(Grade.A, enrollment.Grade);
    }

    [Fact]
    public void Initialize_SomeEnrollmentsHaveNoGrade()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        var anand = context.Students.Single(s => s.LastName == "Anand");
        var enrollment = context.Enrollments
            .Single(e => e.StudentID == anand.ID && e.CourseID == 1050);
        Assert.Null(enrollment.Grade);
    }
}

using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Data;

public class SchoolContextTests
{
    [Fact]
    public void SchoolContext_CanAddAndRetrieveStudent()
    {
        using var context = TestDbContextFactory.Create();
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "Student",
            EnrollmentDate = new DateTime(2023, 1, 1)
        };

        context.Students.Add(student);
        context.SaveChanges();

        var retrieved = context.Students.Find(student.ID);
        Assert.NotNull(retrieved);
        Assert.Equal("Test", retrieved.LastName);
    }

    [Fact]
    public void SchoolContext_CanAddAndRetrieveCourse()
    {
        using var context = TestDbContextFactory.Create();
        var dept = new Department
        {
            Name = "TestDept",
            Budget = 100000,
            StartDate = DateTime.Now
        };
        context.Departments.Add(dept);
        context.SaveChanges();

        var course = new Course
        {
            CourseID = 9001,
            Title = "TestCourse",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };
        context.Courses.Add(course);
        context.SaveChanges();

        var retrieved = context.Courses.Find(9001);
        Assert.NotNull(retrieved);
        Assert.Equal("TestCourse", retrieved.Title);
    }

    [Fact]
    public void SchoolContext_CourseAssignment_HasCompositeKey()
    {
        using var context = TestDbContextFactory.Create();
        var instructor = new Instructor
        {
            LastName = "A",
            FirstMidName = "B",
            HireDate = DateTime.Now,
            CourseAssignments = new List<CourseAssignment>()
        };
        context.Instructors.Add(instructor);

        var dept = new Department { Name = "X", Budget = 1000, StartDate = DateTime.Now };
        context.Departments.Add(dept);
        context.SaveChanges();

        var course = new Course { CourseID = 8001, Title = "Y", Credits = 1, DepartmentID = dept.DepartmentID };
        context.Courses.Add(course);
        context.SaveChanges();

        var assignment = new CourseAssignment { CourseID = course.CourseID, InstructorID = instructor.ID };
        context.CourseAssignments.Add(assignment);
        context.SaveChanges();

        var found = context.CourseAssignments.Find(course.CourseID, instructor.ID);
        Assert.NotNull(found);
    }

    [Fact]
    public void SchoolContext_Instructor_OneToOneOfficeAssignment()
    {
        using var context = TestDbContextFactory.Create();
        var instructor = new Instructor
        {
            LastName = "Office",
            FirstMidName = "Test",
            HireDate = DateTime.Now,
            CourseAssignments = new List<CourseAssignment>()
        };
        context.Instructors.Add(instructor);
        context.SaveChanges();

        var office = new OfficeAssignment { InstructorID = instructor.ID, Location = "Room 42" };
        context.OfficeAssignments.Add(office);
        context.SaveChanges();

        var loaded = context.Instructors
            .Include(i => i.OfficeAssignment)
            .Single(i => i.ID == instructor.ID);
        Assert.Equal("Room 42", loaded.OfficeAssignment!.Location);
    }

    [Fact]
    public void SchoolContext_Enrollment_RelationshipsWork()
    {
        using var context = TestDbContextFactory.Create();
        var student = new Student
        {
            LastName = "Enroll",
            FirstMidName = "Test",
            EnrollmentDate = DateTime.Now
        };
        context.Students.Add(student);

        var dept = new Department { Name = "D", Budget = 1000, StartDate = DateTime.Now };
        context.Departments.Add(dept);
        context.SaveChanges();

        var course = new Course { CourseID = 7001, Title = "C", Credits = 2, DepartmentID = dept.DepartmentID };
        context.Courses.Add(course);
        context.SaveChanges();

        var enrollment = new Enrollment
        {
            StudentID = student.ID,
            CourseID = course.CourseID,
            Grade = Grade.B
        };
        context.Enrollments.Add(enrollment);
        context.SaveChanges();

        var loaded = context.Enrollments
            .Include(e => e.Student)
            .Include(e => e.Course)
            .Single(e => e.EnrollmentID == enrollment.EnrollmentID);
        Assert.Equal(student.ID, loaded.Student!.ID);
        Assert.Equal(course.CourseID, loaded.Course!.CourseID);
        Assert.Equal(Grade.B, loaded.Grade);
    }

    [Fact]
    public void SchoolContext_TPH_StudentAndInstructorInSameTable()
    {
        using var context = TestDbContextFactory.Create();
        context.Students.Add(new Student
        {
            LastName = "S",
            FirstMidName = "T",
            EnrollmentDate = DateTime.Now
        });
        context.Instructors.Add(new Instructor
        {
            LastName = "I",
            FirstMidName = "N",
            HireDate = DateTime.Now,
            CourseAssignments = new List<CourseAssignment>()
        });
        context.SaveChanges();

        // Both inherit from Person - People DbSet contains both
        var people = context.People.ToList();
        Assert.Equal(2, people.Count);
    }

    [Fact]
    public void SchoolContext_Department_CanHaveNullAdministrator()
    {
        using var context = TestDbContextFactory.Create();
        var dept = new Department
        {
            Name = "NoAdmin",
            Budget = 50000,
            StartDate = DateTime.Now,
            InstructorID = null
        };
        context.Departments.Add(dept);
        context.SaveChanges();

        var loaded = context.Departments.Find(dept.DepartmentID);
        Assert.Null(loaded!.InstructorID);
    }
}

